using Microsoft.EntityFrameworkCore;using System.Security.Cryptography;
namespace Decont;
public static class Api {
 public static object View(Report r)=>new{r.Id,r.Number,r.Purpose,r.EmployeeId,r.ManagerId,r.State,r.Version,r.Revision,r.Created,r.Updated,r.RetainUntil,r.LegalHold,total=r.Lines.Where(l=>!l.Archived).Sum(l=>l.Final()),personal=Rules.Personal(r),lines=r.Lines.Where(l=>!l.Archived).OrderBy(l=>l.Position).Select(l=>new{l.Id,l.Position,data=l.Data(),l.EstimatedRon,l.SettledRon,l.Reconciled,l.OverrideReason,l.DuplicateDisposition,l.FxVersion,evidence=l.Evidence.Where(e=>!e.Archived)})};
 public static async Task<IResult> Atomic(Db db,HttpContext c,object request,Func<Task<object>> work){await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);var key=c.Request.Headers["Idempotency-Key"].ToString();Guard.Require(key.Length is >=16 and <=100,"idempotency","Identificatorul operațiunii lipsește.","Operation identifier is missing.",400);var id=Serialization.Hash(Reports.Actor(c.User)+c.Request.Path+key);var hash=Serialization.Hash(Serialization.Write(request));var previous=await db.Idempotencies.FindAsync(id);if(previous!=null){Guard.Require(previous.RequestHash==hash,"idempotency_conflict","Identificatorul a fost reutilizat.","Operation identifier reused with different data.",409);return Results.Text(previous.Response,"application/json");}var result=await work();var response=Serialization.Write(result);db.Idempotencies.Add(new(){Id=id,Actor=Reports.Actor(c.User),RequestHash=hash,Response=response});await db.SaveChangesAsync();await tx.CommitAsync();return Results.Text(response,"application/json");}
 public static void Map(RouteGroupBuilder api){
  api.MapGet("/reports",async(Reports svc,HttpContext c)=>{var rows=await svc.Scope(c.User).Include(r=>r.Lines).ToListAsync();return rows.OrderByDescending(r=>r.Updated).Select(View);});
  api.MapPost("/reports",async(CreateReport i,Reports svc,Db db,HttpContext c)=>await Atomic(db,c,i,async()=>View(await svc.Create(c.User,i.Purpose))));
  api.MapGet("/reports/{id:guid}",async(Guid id,Reports svc,Db db,HttpContext c)=>{var r=await svc.Get(id,c.User);return Results.Ok(new{report=View(r),issues=await svc.Validate(r),timeline=await db.Audits.Where(a=>a.ReportId==id).OrderBy(a=>a.At).ToListAsync(),decisions=await db.Decisions.Where(d=>d.ReportId==id).ToListAsync(),snapshots=await db.Snapshots.Where(s=>s.ReportId==id).Select(s=>new{s.Revision,s.Hash,s.At,s.Actor}).ToListAsync()});});
  api.MapPatch("/reports/{id:guid}",async(Guid id,ReportEdit i,Reports svc,Db db,HttpContext c)=>await Atomic(db,c,i,async()=>{var r=await svc.Version(id,i.Version,c.User);svc.Edit(r,c.User,i.Reason);var before=r.Purpose;r.Purpose=i.Purpose.Trim();Reports.Touch(r);svc.Log(c.User,id,"Report","PurposeChanged",before,r.Purpose,i.Reason);return View(r);}));
  api.MapPost("/reports/{id:guid}/lines",async(Guid id,LineEdit i,Reports svc,Db db,HttpContext c)=>await Atomic(db,c,i,async()=>{var r=await svc.Version(id,i.Version,c.User);svc.Edit(r,c.User,i.Reason);Guard.Require(r.Lines.Count(l=>!l.Archived)<50,"limit","Limita este de 50 de cheltuieli.","Maximum 50 expenses.");var l=new Line{ReportId=id,Position=r.Lines.Count+1};await svc.Apply(l,i.Data);r.Lines.Add(l);db.Lines.Add(l);Reports.Touch(r);svc.Log(c.User,id,l.Id.ToString(),"LineAdded",after:i.Data,reason:i.Reason);await svc.Reapproval(r,c.User);return View(r);}));
  api.MapPatch("/reports/{id:guid}/lines/{lineId:guid}",async(Guid id,Guid lineId,LineEdit i,Reports svc,Db db,HttpContext c)=>await Atomic(db,c,i,async()=>{var r=await svc.Version(id,i.Version,c.User);svc.Edit(r,c.User,i.Reason);var l=r.Lines.Single(l=>l.Id==lineId&&!l.Archived);var before=l.Json;await svc.Apply(l,i.Data);Reports.Touch(r);svc.Log(c.User,id,lineId.ToString(),"LineChanged",before,i.Data,i.Reason);await svc.Reapproval(r,c.User);return View(r);}));
  api.MapPost("/reports/{id:guid}/lines/{lineId:guid}/archive",async(Guid id,Guid lineId,VersionRequest i,Reports svc,Db db,HttpContext c)=>await Atomic(db,c,i,async()=>{var r=await svc.Version(id,i.Version,c.User);svc.Edit(r,c.User,i.Reason);var l=r.Lines.Single(l=>l.Id==lineId&&!l.Archived);Guard.Require(!await db.Matches.AnyAsync(m=>m.LineId==lineId),"matched","Anulează asocierea cardului.","Undo the card match first.");l.Archived=true;Reports.Touch(r);svc.Log(c.User,id,lineId.ToString(),"LineArchived",before:l.Json,reason:i.Reason);return View(r);}));
  api.MapPost("/reports/{id:guid}/lines/{lineId:guid}/duplicate",async(Guid id,Guid lineId,VersionRequest i,Reports svc,Db db,HttpContext c)=>await Atomic(db,c,i,async()=>{var r=await svc.Version(id,i.Version,c.User);svc.Edit(r,c.User,i.Reason);Guard.Require(r.Lines.Count(l=>!l.Archived)<50,"limit","Limita este de 50.","Maximum 50 expenses.");var source=r.Lines.Single(l=>l.Id==lineId&&!l.Archived);var copy=new Line{ReportId=id,Position=r.Lines.Count+1,Json=source.Json,EstimatedRon=source.EstimatedRon,FxVersion=source.FxVersion};r.Lines.Add(copy);db.Lines.Add(copy);Reports.Touch(r);svc.Log(c.User,id,copy.Id.ToString(),"LineDuplicated",after:new{source=lineId},reason:i.Reason);await svc.Reapproval(r,c.User);return View(r);}));
  api.MapPost("/reports/{id:guid}/submit",async(Guid id,VersionRequest i,Reports svc,Db db,HttpContext c)=>await Atomic(db,c,i,async()=>{var r=await svc.Version(id,i.Version,c.User);await svc.Submit(r,c.User);return View(r);}));
  api.MapPost("/reports/{id:guid}/actions/{action}",async(Guid id,string action,VersionRequest i,Reports svc,Db db,HttpContext c)=>await Atomic(db,c,i,async()=>{var r=await svc.Version(id,i.Version,c.User);await svc.Action(r,c.User,action,i.Reason);return View(r);}));
  api.MapGet("/reports/{id:guid}/snapshots/{revision:int}",async(Guid id,int revision,Reports svc,Db db,HttpContext c)=>{await svc.Get(id,c.User);var s=await db.Snapshots.SingleAsync(s=>s.ReportId==id&&s.Revision==revision);return Results.Text(s.Json,"application/json");});
  api.MapGet("/rules",async(HttpContext c,Db db)=>{var q=c.Request.Query;var d=new ExpenseData("","","",q["date"].ToString(),q["country"].ToString(),q["documentType"].ToString(),q["category"].ToString(),"",q["payment"].ToString(),null,"",null,0,q["currency"].ToString(),[]);return Rules.FieldStates(d,await db.Masters.ToListAsync());});
  api.MapGet("/masters",async(Db db)=>await db.Masters.Where(m=>new[]{"costCenters","projects","expenseTypes","cards","vat","fx"}.Contains(m.Kind)).ToListAsync());
  api.MapGet("/notices",async(Db db,HttpContext c)=>await db.Notices.Where(n=>n.UserId==Reports.Actor(c.User)).OrderByDescending(n=>n.At).Take(100).ToListAsync());
  api.MapPost("/notices/{id:guid}/read",async(Guid id,Db db,HttpContext c)=>{await db.Notices.Where(n=>n.Id==id&&n.UserId==Reports.Actor(c.User)).ExecuteUpdateAsync(s=>s.SetProperty(n=>n.Read,true));return Results.NoContent();});
  api.MapPost("/reports/{id:guid}/lines/{lineId:guid}/evidence",async(Guid id,Guid lineId,HttpContext c,Db db,Reports svc,IStore store)=>{var form=await c.Request.ReadFormAsync();Guard.Require(long.TryParse(form["version"],out var version),"version","Versiune lipsă.","Version missing.");var file=form.Files.GetFile("file")??throw new DomainException("file","Selectează un fișier.","Select a file.");Guard.Require(file.Length>0&&file.Length<=Files.MaxFile,"file_size","Limita este de 25 MB.","File limit is 25 MB.");await using var tx=await db.Database.BeginTransactionAsync();var r=await svc.Version(id,version,c.User);svc.Edit(r,c.User,form["reason"]);var l=r.Lines.Single(l=>l.Id==lineId&&!l.Archived);Guard.Require(r.Lines.SelectMany(l=>l.Evidence).Sum(e=>e.Size)+file.Length<=Files.MaxReport,"report_size","Limita este de 200 MB per decont.","Report file limit is 200 MB.");using var ms=new MemoryStream();await file.CopyToAsync(ms);var bytes=ms.ToArray();var e=new Evidence{LineId=lineId,Name=Path.GetFileName(file.FileName),Mime=Files.Mime(bytes,file.FileName),Size=bytes.Length,Hash=Convert.ToHexString(SHA256.HashData(bytes))};e.Key=$"originals/{id}/{e.Id}";await store.Put(e.Key,bytes,e.Mime);l.Evidence.Add(e);db.Evidence.Add(e);db.Jobs.Add(new(){Kind="Scan",Json=e.Id.ToString()});Reports.Touch(r);svc.Log(c.User,id,e.Id.ToString(),"EvidenceUploaded",after:new{e.Name,e.Hash,e.Size});await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(new{e,r.Version});});
  api.MapGet("/evidence/{id:guid}",async(Guid id,Db db,Reports svc,IStore store,HttpContext c)=>{var e=await db.Evidence.SingleAsync(e=>e.Id==id);var l=await db.Lines.SingleAsync(l=>l.Id==e.LineId);await svc.Get(l.ReportId,c.User);Guard.Require(e.Scan=="Clean","quarantine","Documentul nu a trecut verificarea.","Document has not passed scanning.");return Results.File(await store.Get(e.Key),e.Mime,enableRangeProcessing:true);});
  api.MapPost("/reports/{id:guid}/evidence/{eid:guid}/archive",async(Guid id,Guid eid,VersionRequest i,Db db,Reports svc,HttpContext c)=>await Atomic(db,c,i,async()=>{var r=await svc.Version(id,i.Version,c.User);svc.Edit(r,c.User,i.Reason);var e=r.Lines.SelectMany(l=>l.Evidence).Single(e=>e.Id==eid);e.Archived=true;Reports.Touch(r);svc.Log(c.User,id,eid.ToString(),"EvidenceArchived",reason:i.Reason);return View(r);}));
 }
}
public record CreateReport(string Purpose);public record ReportEdit(long Version,string Purpose,string? Reason);public record LineEdit(long Version,ExpenseData Data,string? Reason);public record VersionRequest(long Version,string? Reason);
